readonly Dictionary<(int X, int Y), List<Entity>> _cells = new();

List<Entity> Cell(int cx, int cy) =>
    _cells.TryGetValue((cx, cy), out var l) ? l : _cells[(cx, cy)] = new List<Entity>();

void Insert(Entity e) { var (cx, cy) = CellOf(e.Position); Cell(cx, cy).Add(e); }

IEnumerable<Entity> Near(Vec2 p, float r) {
    var (x0, y0) = CellOf(p - new Vec2(r, r));
    var (x1, y1) = CellOf(p + new Vec2(r, r));
    for (int cy = y0; cy <= y1; cy++) for (int cx = x0; cx <= x1; cx++)
        foreach (var e in Cell(cx, cy)) if (Dist(e.Position, p) <= r) yield return e;
}

